import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
const $=s=>document.querySelector(s), scene=new THREE.Scene();
const renderer=new THREE.WebGLRenderer({canvas:$('#game'),antialias:false,powerPreference:'low-power'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
scene.background=new THREE.Color('#a9c5bd');scene.fog=new THREE.Fog('#a9c5bd',95,205);
const camera=new THREE.PerspectiveCamera(62,innerWidth/innerHeight,.1,260);
scene.add(new THREE.HemisphereLight('#e5f1db','#687964',2.0));
const sun=new THREE.DirectionalLight('#fff0d4',2.5);sun.position.set(-45,70,35);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-90;sun.shadow.camera.right=90;sun.shadow.camera.top=90;sun.shadow.camera.bottom=-90;sun.shadow.bias=-.0003;scene.add(sun);
const mat=(color,roughness=1)=>new THREE.MeshStandardMaterial({color,roughness,flatShading:true});
const M={grass:mat('#758c60'),grass2:mat('#8c9b68'),sand:mat('#c9b77f'),water:mat('#477a7b'),trunk:mat('#715b43'),leaf:mat('#557456'),leaf2:mat('#81945f'),rock:mat('#858b7d'),wall:mat('#c5b99c'),roof:mat('#8d6252'),blue:mat('#829ba0'),dark:mat('#28383a'),white:mat('#e6dfc7'),red:mat('#c8674f'),yellow:mat('#dfc96f'),bot:mat('#b9614b'),bot2:mat('#4a7880'),skin:mat('#bd8d69'),black:mat('#303b39'),crate:mat('#9a8159'),glow:new THREE.MeshBasicMaterial({color:'#d8fa69'})};
const terrainHeight=(x,z)=>{let h=1.6*Math.sin(x*.07)*Math.cos(z*.06)+1.2*Math.sin((x+z)*.11)+.55*Math.cos(z*.18+x*.12);let r=Math.hypot(x,z);h+=Math.max(0,1-r/95)*2.1;return h;};
const groundGeo=new THREE.PlaneGeometry(190,190,64,64);groundGeo.rotateX(-Math.PI/2);const pos=groundGeo.attributes.position,colors=[];for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i),h=terrainHeight(x,z);pos.setY(i,h);const c=new THREE.Color(h>3?'#89956a':h<-.8?'#b8ab7d':'#788e62');colors.push(c.r,c.g,c.b);}groundGeo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));groundGeo.computeVertexNormals();const ground=new THREE.Mesh(groundGeo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1,flatShading:true}));ground.receiveShadow=true;scene.add(ground);
const water=new THREE.Mesh(new THREE.CircleGeometry(155,40),mat('#477a7b'));water.rotation.x=-Math.PI/2;water.position.y=-1.9;scene.add(water);
const islandEdge=new THREE.Mesh(new THREE.CylinderGeometry(82,91,9,36,1,true),mat('#826e53'));islandEdge.position.y=-3.9;scene.add(islandEdge);
function addMesh(geo,material,x,y,z,scale){const o=new THREE.Mesh(geo,material);o.position.set(x,y,z);if(scale)o.scale.set(...scale);o.castShadow=true;o.receiveShadow=true;scene.add(o);return o;}
function box(x,y,z,sx,sy,sz,material){return addMesh(new THREE.BoxGeometry(sx,sy,sz),material,x,y,z);}
function randSeed(seed){let s=seed;return()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296;};}const rand=randSeed(7521);
const obstacles=[],loot=[];
function addBuilding(x,z,w,d,h,style=0){const y=terrainHeight(x,z);let wall=style?M.blue:M.wall,roof=style?M.dark:M.roof;box(x,y+h/2,z,w,h,d,wall);box(x,y+h+.18,z,w+1,.4,d+1,roof);for(let xx=-1;xx<=1;xx+=2){box(x+xx*w*.26,y+h*.58,z-d/2-.025,.72,.92,.07,M.dark);box(x+xx*w*.26,y+h*.58,z+d/2+.025,.72,.92,.07,M.dark);}box(x,y+h*.35,z+d/2+.05,.95,h*.7,.12,M.trunk);obstacles.push({x,z,r:Math.max(w,d)*.58});}
addBuilding(-21,-14,12,10,5);addBuilding(18,9,15,12,6,1);addBuilding(33,-25,11,9,4);addBuilding(-34,28,14,10,5,1);addBuilding(2,-39,18,11,5);addBuilding(-48,-14,10,9,4);
// Scattered walls, fences and island landmarks.
for(let i=0;i<22;i++){const x=(rand()-.5)*140,z=(rand()-.5)*140;if(Math.hypot(x,z)<13)continue;const y=terrainHeight(x,z);if(i%3===0){box(x,y+1,z,rand()*5+4,2,rand()*1+.35,i%2?M.wall:M.trunk);obstacles.push({x,z,r:3});}else{const h=rand()*2.5+1.5;addMesh(new THREE.DodecahedronGeometry(h,0),M.rock,x,y+h*.35,z,[1.1,.75,.9]);obstacles.push({x,z,r:h*.8});}}
// Low-poly trees; trunk and two overlapping faceted canopies.
for(let i=0;i<105;i++){const x=(rand()-.5)*150,z=(rand()-.5)*150;if(Math.hypot(x,z)<12||Math.hypot(x,z)>75||obstacles.some(o=>Math.hypot(x-o.x,z-o.z)<5))continue;const y=terrainHeight(x,z),h=2.2+rand()*2.7;addMesh(new THREE.CylinderGeometry(.18,.34,h*.55,5),M.trunk,x,y+h*.26,z);const leafMat=rand()>.5?M.leaf:M.leaf2;addMesh(new THREE.ConeGeometry(h*.42,h*.68,5),leafMat,x,y+h*.83,z);addMesh(new THREE.ConeGeometry(h*.3,h*.48,5),leafMat,x,y+h*1.14,z,[.9,1,.9]);obstacles.push({x,z,r:.9});}
// Central road and painted landing pads.
const road=box(0,terrainHeight(0,0)+.03,0,8,.08,145,mat('#a99a78'));road.rotation.y=.03;
for(let i=0;i<8;i++){const x=(i%2?1:-1)*60,z=-48+i*14;const y=terrainHeight(x,z);const pad=addMesh(new THREE.CylinderGeometry(3.2,3.2,.12,8),mat('#c4b786'),x,y+.05,z);}

