// Central road and painted landing pads.
const road=box(0,terrainHeight(0,0)+.03,0,8,.08,145,mat('#a99a78'));road.rotation.y=.03;
for(let i=0;i<8;i++){const x=(i%2?1:-1)*60,z=-48+i*14;const y=terrainHeight(x,z);addMesh(new THREE.CylinderGeometry(3.2,3.2,.12,8),mat('#c4b786'),x,y+.05,z);}
function makeFighter(isPlayer=false,index=0){const g=new THREE.Group(),clothes=isPlayer?M.dark:(index%3===0?M.bot:index%3===1?M.bot2:M.yellow),skin=M.skin;const torso=addMesh(new THREE.CylinderGeometry(.28,.37,.82,6),clothes,0,1.08,0);const vest=addMesh(new THREE.BoxGeometry(.61,.55,.31),isPlayer?M.blue:(index%2?M.dark:M.trunk),0,1.15,.06);const head=addMesh(new THREE.IcosahedronGeometry(.23,1),skin,0,1.72,0);head.scale.set(.85,1.08,.88);const helmet=addMesh(new THREE.SphereGeometry(.25,6,5),isPlayer?M.yellow:M.dark,0,1.84,0,[1.05,.55,1]);const legs=[];for(const x of [-.16,.16])legs.push(addMesh(new THREE.CylinderGeometry(.12,.15,.55,5),isPlayer?M.dark:clothes,x,.37,0));const gun=addMesh(new THREE.BoxGeometry(.12,.13,.8),M.black,.25,1.15,.48);const barrel=addMesh(new THREE.CylinderGeometry(.035,.035,.42,5),M.dark,.25,1.15,.9);barrel.rotation.x=Math.PI/2;g.add(torso,vest,head,helmet,...legs,gun,barrel);g.position.y=terrainHeight(0,0);scene.add(g);return {group:g,torso,head,legs,gun,barrel};}
const player=makeFighter(true);player.group.position.set(0,terrainHeight(0,0),0);player.position=new THREE.Vector3(0,terrainHeight(0,0),0);player.velocityY=0;player.yaw=0;player.hp=100;player.armor=0;player.armorLevel=0;player.kits=2;player.onGround=true;player.crouch=false;
const bots=[],botNames=['ROOK','MICA','DUST','KITE','FABLE','VEX','NOVA','BRICK','ECHO','SABLE','RIFT','JUNO','ASH','TALON','ONYX','WREN','FLINT'];
for(let i=0;i<17;i++){let a=rand()*Math.PI*2,r=25+rand()*43,x=Math.cos(a)*r,z=Math.sin(a)*r;const avatar=makeFighter(false,i);avatar.group.position.set(x,terrainHeight(x,z),z);bots.push({id:i,name:botNames[i],group:avatar.group,avatar,hp:100,alive:true,x,z,yaw:rand()*Math.PI*2,weapon:i%4===0?'shotgun':i%5===0?'sniper':'rifle',think:rand()*2,fire:1+rand()*3,roam:rand()*6,tx:x,tz:z,armor:i%4===0?35:0});}
const weaponDefs={rifle:{name:'ASSAULT RIFLE',type:'RIFLE // FULL AUTO',icon:'⌁',magSize:30,reserve:120,damage:19,rate:.115,range:75,spread:.025},shotgun:{name:'TACTICAL SHOTGUN',type:'SHOTGUN // 8-PELLET BURST',icon:'▰',magSize:8,reserve:40,damage:10,rate:.72,range:25,spread:.13,pellets:7},sniper:{name:'MARKSMAN RIFLE',type:'SNIPER // HIGH IMPACT',icon:'⌖',magSize:5,reserve:25,damage:78,rate:1.05,range:120,spread:.009}};
let weapon='rifle',mag=30,reserve=120,reloading=0,lastShot=0,kills=0,matchTime=0,playing=false,ended=false,aliveCount=18,toastTimer=0,hitTimer=0,zonePhase=0,zoneTimer=80,zoneRadius=77,zoneNext=77,zoneCenter={x:0,z:0},zoneDamageTimer=0;
const zoneMat=new THREE.MeshBasicMaterial({color:'#66dbea',transparent:true,opacity:.105,side:THREE.DoubleSide,depthWrite:false});const zoneWall=new THREE.Mesh(new THREE.CylinderGeometry(1,1,18,64,1,true),zoneMat);zoneWall.position.y=7;scene.add(zoneWall);const zoneFloor=new THREE.Mesh(new THREE.RingGeometry(.985,1,64),new THREE.MeshBasicMaterial({color:'#85eff0',transparent:true,opacity:.7,side:THREE.DoubleSide}));zoneFloor.rotation.x=-Math.PI/2;zoneFloor.position.y=terrainHeight(0,0)+.2;scene.add(zoneFloor);
function addLoot(x,z,type){const y=terrainHeight(x,z)+.45,group=new THREE.Group(),color=type==='medkit'?'#d8fa69':type==='armor'?'#70e1e4':type==='ammo'?'#edca76':type==='shotgun'?'#ff9b67':type==='sniper'?'#c3a2eb':'#b8d386';const cube=new THREE.Mesh(new THREE.BoxGeometry(.68,.55,.68),mat(color));cube.castShadow=true;group.add(cube);const ring=new THREE.Mesh(new THREE.TorusGeometry(.56,.035,5,12),new THREE.MeshBasicMaterial({color}));ring.rotation.x=Math.PI/2;ring.position.y=-.17;group.add(ring);group.position.set(x,y,z);scene.add(group);loot.push({x,z,type,group,phase:rand()*6});}
for(let i=0;i<72;i++){const a=rand()*Math.PI*2,r=8+rand()*67,x=Math.cos(a)*r,z=Math.sin(a)*r;if(obstacles.some(o=>Math.hypot(x-o.x,z-o.z)<2.5))continue;const roll=rand();addLoot(x,z,roll<.15?'medkit':roll<.30?'armor':roll<.48?'ammo':roll<.66?'shotgun':roll<.79?'sniper':'rifle');}

