function updateCamera(dt){const target=player.position.clone().add(new THREE.Vector3(0,player.crouch?1.15:1.55,0));const dist=player.crouch?5.3:6.2;const desired=new THREE.Vector3(target.x+Math.sin(cameraYaw)*dist,target.y+1.1+cameraPitch*5,target.z+Math.cos(cameraYaw)*dist);camera.position.lerp(desired,1-Math.exp(-dt*8));camera.lookAt(target.x,target.y+cameraPitch*1.6,target.z);}
function moveEntity(ent,dx,dz){let nx=THREE.MathUtils.clamp(ent.x+dx,-82,82),nz=THREE.MathUtils.clamp(ent.z+dz,-82,82);for(const ob of obstacles){const ox=nx-ob.x,oz=nz-ob.z,d=Math.hypot(ox,oz),min=ob.r+.42;if(d<min&&d>0){nx=ob.x+ox/d*min;nz=ob.z+oz/d*min;}}ent.x=nx;ent.z=nz;}
function updatePlayer(dt){let mx=move.x+(keys.KeyD?1:0)-(keys.KeyA?1:0),my=move.y+(keys.KeyW?1:0)-(keys.KeyS?1:0);const len=Math.hypot(mx,my);if(len>1){mx/=len;my/=len;}const sprint=keys.ShiftLeft||keys.ShiftRight,speed=player.crouch?2.1:sprint?8.5:5.7;const fx=-Math.sin(cameraYaw),fz=-Math.cos(cameraYaw),rx=Math.cos(cameraYaw),rz=-Math.sin(cameraYaw);const dx=(fx*my+rx*mx)*speed*dt,dz=(fz*my+rz*mx)*speed*dt;moveEntity(player,dx,dz);const targetY=terrainHeight(player.position.x,player.position.z);if(!player.onGround){player.velocityY-=17*dt;player.position.y+=player.velocityY*dt;if(player.position.y<=targetY){player.position.y=targetY;player.velocityY=0;player.onGround=true;}}else player.position.y=targetY;player.group.position.set(player.position.x,player.position.y,player.position.z);player.group.rotation.y=cameraYaw+Math.PI;const walk=Math.min(1,len);player.avatar.legs[0].rotation.x=Math.sin(matchTime*10)*walk*.5;player.avatar.legs[1].rotation.x=-Math.sin(matchTime*10)*walk*.5;player.avatar.torso.rotation.z=mx*.08;player.group.position.y+=walk?Math.abs(Math.sin(matchTime*10))*.045:0;updateCamera(dt);}
function updateBots(dt){for(const b of bots){if(!b.alive)continue;b.think-=dt;b.fire-=dt;b.roam-=dt;const distPlayer=Math.hypot(player.position.x-b.x,player.position.z-b.z);let target=null;if(player.hp>0&&distPlayer<38)target={player:true,x:player.position.x,z:player.position.z,d:distPlayer};let rival=null,rivalDist=22;for(const other of bots){if(other===b||!other.alive)continue;const d=Math.hypot(other.x-b.x,other.z-b.z);if(d<rivalDist){rival=other;rivalDist=d;}}if(rival&&(!target||rivalDist<target.d*.72))target={bot:rival,x:rival.x,z:rival.z,d:rivalDist};
