 function updateZone(dt){zoneTimer-=dt;zoneWall.position.set(zoneCenter.x,7,zoneCenter.z);zoneWall.scale.set(zoneRadius,1,zoneRadius);zoneFloor.position.set(zoneCenter.x,terrainHeight(zoneCenter.x,zoneCenter.z)+.22,zoneCenter.z);zoneFloor.scale.set(zoneRadius,zoneRadius,1);if(zoneTimer<=0&&zonePhase<4){zonePhase++;zoneRadius=zonePhase===1?58:zonePhase===2?39:zonePhase===3?23:9;zoneNext=zoneRadius;zoneTimer=zonePhase===4?48:55;zoneCenter.x+=(rand()-.5)*14;zoneCenter.z+=(rand()-.5)*14;showToast('SAFE ZONE SHRINKING');beep(260,.4,'sine');}const outside=Math.hypot(player.position.x-zoneCenter.x,player.position.z-zoneCenter.z)>zoneRadius;if(outside){zoneDamageTimer-=dt;if(zoneDamageTimer<=0){playerDamage(4);zoneDamageTimer=2;}}for(const b of bots){if(!b.alive)continue;if(Math.hypot(b.x-zoneCenter.x,b.z-zoneCenter.z)>zoneRadius){b.hp-=dt*(zonePhase>1?5:3);if(b.hp<=0)botEliminate(b,false);}}const mm=Math.floor(Math.max(0,zoneTimer));$('#zone-time').textContent=String(Math.floor(mm/60)).padStart(2,'0')+':'+String(mm%60).padStart(2,'0');$('#zone-time').style.color=outside?'#ff8469':'#fff';}
 function drawMap(){const c=$('#minimap'),ctx=c.getContext('2d'),w=c.width,h=c.height,scale=w/180;ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(w/2,h/2);ctx.fillStyle='#748b65';ctx.beginPath();ctx.arc(0,0,w*.47,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#c9b77f';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(-2,-w*.46);ctx.lineTo(3,w*.46);ctx.stroke();ctx.fillStyle='#a18b68';for(const ob of obstacles){ctx.beginPath();ctx.arc(ob.x*scale,ob.z*scale,Math.max(1.5,ob.r*scale*.3),0,Math.PI*2);ctx.fill();}ctx.strokeStyle='#8de8eb';ctx.lineWidth=2;ctx.beginPath();ctx.arc(zoneCenter.x*scale,zoneCenter.z*scale,zoneRadius*scale,0,Math.PI*2);ctx.stroke();for(const b of bots){if(!b.alive)continue;ctx.fillStyle='#ff765d';ctx.fillRect(b.x*scale-2,b.z*scale-2,4,4);}ctx.fillStyle='#e3fa76';ctx.beginPath();ctx.arc(player.position.x*scale,player.position.z*scale,4,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#f6ffe8';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(player.position.x*scale,player.position.z*scale);ctx.lineTo(player.position.x*scale-Math.sin(cameraYaw)*9,player.position.z*scale-Math.cos(cameraYaw)*9);ctx.stroke();ctx.restore();}
